SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.careunit, COUNT(a.hadm_id) AS admission_count, AVG(l.value) AS avg_imaging_value FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN chartevents c ON a.hadm_id = c.hadm_id JOIN labevents l ON c.charttime = l.charttime AND c.itemid = l.itemid WHERE p.gender = 'M' AND p.anchor_age BETWEEN 49 AND 59 AND p.anchor_year = 2019 AND p.anchor_year_group = 'Primary heart failure' AND p.subject_id = 54 AND i.careunit IN ('ICU', 'CCU') AND l.value_uom IN ('CT', 'MRI') AND l.charttime BETWEEN a.admittime AND a.dischtime AND (l.charttime - a.admittime) BETWEEN 1 AND 7 GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.careunit, i.los ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.careunit, i.los NULLS LAST;